<?php
session_start(); require __DIR__.'/db.php';
$msg='';
if(isset($_GET['logout'])){unset($_SESSION['customer']);header('Location: account.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['register'])){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$msg='Completează corect datele. Parola trebuie să aibă minimum 8 caractere.';else{try{$s=$pdo->prepare('INSERT INTO customers(name,email,phone,address,password_hash) VALUES(?,?,?,?,?)');$s->execute([$name,$email,trim($_POST['phone']??''),trim($_POST['address']??''),password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['customer']=$pdo->query("SELECT LASTVAL()")->fetchColumn();header('Location: account.php');exit;}catch(Throwable $e){$msg='Există deja un cont cu acest email.';}}}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['login'])){$s=$pdo->prepare('SELECT * FROM customers WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){$_SESSION['customer']=$u['id'];header('Location: account.php');exit;}$msg='Email sau parolă incorectă.';}
?><!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contul meu — CreativArt</title><link rel="stylesheet" href="assets/style.css"><style>.account{max-width:900px;margin:40px auto;padding:20px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{background:#fff;padding:24px;border-radius:18px;box-shadow:0 8px 30px #0001}.panel input,.panel textarea{width:100%;padding:12px;margin:6px 0}.panel button{padding:12px 18px;background:#e8ad43;border:0;border-radius:10px}@media(max-width:700px){.forms{grid-template-columns:1fr}}</style></head><body><main class="account"><p><a href="./">← Magazin</a></p><h1>Contul meu</h1><?php if($msg):?><p><?=htmlspecialchars($msg)?></p><?php endif;?><?php if(isset($_SESSION['customer'])):$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$_SESSION['customer']]);$u=$s->fetch();$q=$pdo->prepare('SELECT * FROM orders WHERE customer_id=? OR email=? ORDER BY id DESC');$q->execute([$u['id'],$u['email']]);$orders=$q->fetchAll();?><div class="panel"><h2>Bun venit, <?=htmlspecialchars($u['name'])?></h2><p><?=htmlspecialchars($u['email'])?> · <?=htmlspecialchars($u['phone'])?></p><p><a href="?logout=1">Deconectare</a></p><h2>Comenzile mele</h2><?php if(!$orders):?><p>Nu ai încă nicio comandă.</p><?php endif;?><?php foreach($orders as $o):?><p><strong>#<?=$o['id']?></strong> — <?=number_format($o['total'],2,',',' ')?> lei — <b><?=htmlspecialchars($o['status'])?></b> — <?=$o['created_at']?></p><?php endforeach;?></div><?php else:?><div class="forms"><form method="post" class="panel"><h2>Autentificare</h2><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Parolă" required><button name="login">Intră în cont</button></form><form method="post" class="panel"><h2>Creează cont</h2><input name="name" placeholder="Nume și prenume" required><input type="email" name="email" placeholder="Email" required><input name="phone" placeholder="Telefon"><textarea name="address" placeholder="Adresă"></textarea><input type="password" name="password" placeholder="Parolă (min. 8 caractere)" required><button name="register">Creează cont</button></form></div><?php endif;?></main></body></html>